"use strict";(self.webpackChunkdocusaurus_site=self.webpackChunkdocusaurus_site||[]).push([["359"],{6340(e,i,n){n.r(i),n.d(i,{metadata:()=>t,default:()=>f,frontMatter:()=>c,contentTitle:()=>h,toc:()=>m,assets:()=>d});var t=JSON.parse('{"id":"multisensory-experience/multisensory-experience-practical-insights","title":"Practical insights","description":"Practical insights 8 min","source":"@site/docs/04-multisensory-experience/03-practical-insights.mdx","sourceDirName":"04-multisensory-experience","slug":"/multisensory-experience/practical-insights","permalink":"/multisensory-experience/practical-insights","draft":false,"unlisted":false,"editUrl":null,"tags":[],"version":"current","sidebarPosition":3,"frontMatter":{"title":"Practical insights","id":"multisensory-experience-practical-insights","slug":"practical-insights","sidebar_position":3,"custom_edit_url":null,"readingTimeMinutes":8},"sidebar":"reportSidebar","previous":{"title":"Creative opportunities: Boosting presence","permalink":"/multisensory-experience/creative-opportunities-boosting-presence"},"next":{"title":"In focus: Vision","permalink":"/in-focus-vision/"}}'),s=n(4848),a=n(8453);n(9226),n(5618),n(8238),n(1367),n(9089),n(8839);var r=n(3439);n(8461);var o=n(6489),l=n(2621);let c={title:"Practical insights",id:"multisensory-experience-practical-insights",slug:"practical-insights",sidebar_position:3,custom_edit_url:null,readingTimeMinutes:8},h,d={},m=[{value:'Practical insights <span class="reading-time"><span>8 min</span></span>',id:"practical-insights-8-min",level:2},{value:"Latency tolerances",id:"latency-tolerances",level:3},{value:"Tolerance of spatial mismatches",id:"tolerance-of-spatial-mismatches",level:3},{value:"Prior experience and the assumption of unity",id:"prior-experience-and-the-assumption-of-unity",level:3},{value:"Perceptual &#39;filling in&#39;",id:"perceptual-filling-in",level:3},{value:"Multisensory attention",id:"multisensory-attention",level:3},{value:"Holistic experiential integration",id:"holistic-experiential-integration",level:3}];function u(e){let i={em:"em",h2:"h2",h3:"h3",img:"img",li:"li",p:"p",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsxs)(i.h2,{id:"practical-insights-8-min",children:["Practical insights ",(0,s.jsx)("span",{className:"reading-time",role:"note","aria-label":"8 minute read",children:(0,s.jsx)("span",{"aria-hidden":"true",children:"8 min"})})]}),"\n",(0,s.jsx)(l.A,{blockId:"page-multisensory-experience-practical-insights-6be5424a",topic:"multisensory",label:"Practical insights"}),"\n",(0,s.jsx)(i.h3,{id:"latency-tolerances",children:"Latency tolerances"}),"\n",(0,s.jsx)("span",{className:"reading-time reading-time--section",role:"note","aria-label":"4 minute read",children:(0,s.jsx)("span",{"aria-hidden":"true",children:"4 min"})}),"\n",(0,s.jsxs)(i.p,{children:["It is popular to benchmark creative technical solutions in terms of ",(0,s.jsxs)(i.em,{children:["quality of service",(0,s.jsx)(o.A,{refNum:"48",refText:"Reference 48"})]}),", which encompasses computer science related terms such as* bandwidth*,* jitter*,* packet loss ",(0,s.jsx)(i.em,{children:"and"})," latency*. Audiences on the other hand are concerned with the* quality ",(0,s.jsx)(i.em,{children:"of ex"}),"perience",(0,s.jsx)(o.A,{refNum:"48",refText:"Reference 48"}),"*, encompassing subjective terms such as smoothness, responsiveness, comfort and immersion."]}),"\n",(0,s.jsxs)(i.p,{children:["These two do not always align. Solutions that technically fall short in terms of strict ",(0,s.jsx)(i.em,{children:"quality of service"})," thresholds can sometimes still deliver a satisfying experience if they remain within perceptual tolerance windows. On the other hand, despite meeting ",(0,s.jsx)(i.em,{children:"quality of service"})," thresholds, something might feel ",(0,s.jsx)(i.em,{children:"just off"})," about an experience without careful thought to multisensory elements. This distinction helps guide where creative effort and technical effort are best invested."]}),"\n",(0,s.jsxs)(i.p,{children:["It is often difficult to ensure that information being presented to different senses arrives at exactly the same time. Fortunately, in integrating sensory information our brains can tolerate small mismatches in timing. This means that absolute zero-latency is not always necessary for an engaging, comfortable experience. The graph below illustrates the lags reported as acceptable, or as not noticeable, for different tasks and types of information, alongside everyday sound-travel times for comparisonshay",(0,s.jsx)(o.A,{refNum:"49\u201355",refText:"References 49\u201355"})," ."]}),"\n",(0,s.jsx)(r.A,{}),"\n",(0,s.jsx)(i.p,{children:"These considerations are important in a range of different screen, performance and gaming contexts. The following are some illustrative examples:"}),"\n",(0,s.jsxs)(i.ul,{children:["\n",(0,s.jsxs)(i.li,{children:["\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.strong,{children:"Motion-to-Photon Latency in Gaming"}),": When a player moves their character, a traditional view is that there should be a minimal delay before this movement is reflected on screen. This delay is known as motion-to-photon latency. Studies on first-person targeting and competitive FPS play show that reducing local latency improves performance; performance differences are already measurable in the tens-of-milliseconds range",(0,s.jsx)(o.A,{refNum:"56,57",refText:"References 56,57"}),"."]}),"\n"]}),"\n",(0,s.jsxs)(i.li,{children:["\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.strong,{children:"Remote Collaborative Performances"}),": When actors or musicians collaborate from different locations on the map, delays in audio and visual transmission can disrupt the natural flow of interaction, which can influence the quality of their performance and expressive nuance",(0,s.jsx)(o.A,{refNum:"58",refText:"Reference 58"}),". In networked music performance, 20\u201330 ms is often cited as a target that feels close to in-person playing, although tolerable delay depends on repertoire, rhythm and performer adaptation",(0,s.jsx)(o.A,{refNum:"59",refText:"Reference 59"}),". That being said, large orchestras, spread over a 40ft area (12.2m), would have delays of 35\u201336 ms milliseconds due to speed of sound, implying that there are workarounds to this issue",(0,s.jsx)(o.A,{refNum:"49",refText:"Reference 49"}),'. Out of curiosity, it is worth noting a striking parallel: the band AC/DC often performed within a few feet of each other, with Malcolm Young (rhythm guitar), Cliff Williams (bass) and Phil Rudd (drums) positioned very close and maintaining their famously precise rhythmic tightness: "',(0,s.jsx)(i.em,{children:"They didn't just play in time, they felt the time \u2014 the groove \u2014 together"}),'."',(0,s.jsx)(o.A,{refNum:"60",refText:"Reference 60"})]}),"\n"]}),"\n",(0,s.jsxs)(i.li,{children:["\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.strong,{children:"Live Music Streaming"}),": When streaming a live music performance into viewers' homes, it is important to consider how latency affects the experience. A small mismatch between audio and video can be tolerated, but the acceptable limits depend on which signal leads. For broadcast-style audiovisual sync, viewers begin to detect mismatch at roughly 45 ms when audio leads video and 125 ms when video leads audio, and judge it unacceptable beyond roughly 90 ms and 185 ms respectively.",(0,s.jsx)(o.A,{refNum:"53",refText:"Reference 53"})]}),"\n"]}),"\n",(0,s.jsx)(i.li,{}),"\n",(0,s.jsxs)(i.li,{children:["\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.strong,{children:"Arena-scale performances"}),": Sound travels through air at approximately 343 meters per second, meaning it takes about 2.9 milliseconds to travel 1 metre. If you sit 10 metres from a stage, you will hear the performer about 29 milliseconds later than someone in the front row. Temperature also has a significant effect: the speed of sound increases by around 0.5\u20130.6 m/s for each 1\xb0C rise in air temperature",(0,s.jsx)(o.A,{refNum:"61",refText:"Reference 61"}),", with smaller contributions from humidity and air pressure. High frequencies are more dampened than lower frequencies, leading to a loss of brightness over distance. Here's an interesting thought: if a performer's mouth occupies about 2\xa0cm in your visual field at 1\xa0m but only 0.2\xa0cm at 10\xa0m (simply due to physics), lip-sync errors may be less perceptually obvious at that distance \u2014 but timing differences in sound remain important. This is one reason large venues and festivals strategically distribute speakers (",(0,s.jsx)(i.em,{children:"delay towers"}),") to keep sound aligned across the audience area. A known issue is that audience members located between two towers may hear slightly misaligned signals, creating a hollow or echo-like effect. Much of the craft of setting up public address systems involves tuning these time delays and shaping directivity patterns to minimise overlap and interference",(0,s.jsx)(o.A,{refNum:"55,62",refText:"References 55,62"}),"."]}),"\n"]}),"\n"]}),"\n",(0,s.jsxs)(i.p,{children:["Tolerances also vary substantially from person to person. For example, children typically have a higher tolerance for audiovisual delays than adults",(0,s.jsx)(o.A,{refNum:"63",refText:"Reference 63"}),", people with Attention Deficit/Hyperactivity Disorder (ADHD) tend to have a lower tolerance",(0,s.jsx)(o.A,{refNum:"64",refText:"Reference 64"})," (narrower windows; note some recent counter evidence exists",(0,s.jsx)(o.A,{refNum:"65",refText:"Reference 65"}),"), and individuals with developmental dyslexia",(0,s.jsx)(o.A,{refNum:"66",refText:"Reference 66"})," or with schizophrenia",(0,s.jsx)(o.A,{refNum:"67",refText:"Reference 67"})," generally display higher tolerances (broader windows) for the same lags. Because inclusive design should cater for all, including the most sensitive groups, latency ",(0,s.jsx)(i.em,{children:"budgets"})," ought to be set just below the smallest empirically reported window, even if larger windows appear acceptable for other audiences."]}),"\n",(0,s.jsx)(i.h3,{id:"tolerance-of-spatial-mismatches",children:"Tolerance of spatial mismatches"}),"\n",(0,s.jsx)("span",{className:"reading-time reading-time--section",role:"note","aria-label":"1 minute read",children:(0,s.jsx)("span",{"aria-hidden":"true",children:"1 min"})}),"\n",(0,s.jsxs)(i.p,{children:["When sensory signals appear in roughly the same location, our brains tend to merge them. Interestingly, this principle can hold even if there is a small but noticeable gap. For example, in a ventriloquist's performance the puppeteer's mouth is the true source of sound, yet onlookers often perceive the puppet itself as talking",(0,s.jsx)(o.A,{refNum:"68",refText:"Reference 68"}),". Even when there is a 30\xb0 separation",(0,s.jsx)(o.A,{refNum:"69",refText:"Reference 69"})," between the puppet and the ventriloquist's mouth, observers often fuse the two (the effect is strongest when the separation is small, within roughly 10\u201315\xb0). A variety of factors influence the level of acceptable variation, as outlined in the next section."]}),"\n",(0,s.jsx)(i.h3,{id:"prior-experience-and-the-assumption-of-unity",children:"Prior experience and the assumption of unity"}),"\n",(0,s.jsx)("span",{className:"reading-time reading-time--section",role:"note","aria-label":"1 minute read",children:(0,s.jsx)("span",{"aria-hidden":"true",children:"1 min"})}),"\n",(0,s.jsxs)(i.p,{children:["If we believe that two signals share the same origin, our brains can tolerate more pronounced mismatches in timing or location than usual. Early work",(0,s.jsx)(o.A,{refNum:"70",refText:"Reference 70"})," showed that simply expecting signals to come from one source can override some discrepancies in timing or location. This is known as the ",(0,s.jsx)(i.em,{children:"assumption of unity"})," and it is strongly influenced by prior experience \u2013 the brain learns from repeated multisensory encounters, building strong associations that guide whether future signals are integrated."]}),"\n",(0,s.jsx)(i.p,{children:(0,s.jsx)(i.img,{alt:"Black and white photograph showing a section of a cratered planetary surface with several raised, rounded formations resembling faces. The formations stand out due to shadows and light contrasts, highlighting unusual shapes amid a textured, pockmarked terrain.",src:n(7006).A+"",width:"640",height:"472"})}),"\n",(0,s.jsxs)(i.p,{children:["The ",(0,s.jsx)(i.em,{children:(0,s.jsx)(i.strong,{children:"Face on Mars"})})," captured by NASA's ",(0,s.jsx)(i.em,{children:"Viking 1 orbiter"})," in 1976. This image is often cited as a classic example of pareidolia: the human tendency to perceive meaningful patterns, such as faces, in random or ambiguous visual data. \xa9 NASA/JPL, Viking 1 Orbiter, 1976."]}),"\n",(0,s.jsx)(i.h3,{id:"perceptual-filling-in",children:"Perceptual 'filling in'"}),"\n",(0,s.jsx)("span",{className:"reading-time reading-time--section",role:"note","aria-label":"1 minute read",children:(0,s.jsx)("span",{"aria-hidden":"true",children:"1 min"})}),"\n",(0,s.jsxs)(i.p,{children:["Our brains often ",(0,s.jsx)(i.em,{children:"fill in"})," missing or messy sensory data, drawing on past knowledge and context to create an experience that is fuller than that of the sensory information provided. An example of this is pareidolia, the tendency to see meaningful patterns in random or ambiguous things. This is why we might see a face on the surface of the moon or a human figure in the shadows on a dark street",(0,s.jsx)(o.A,{refNum:"71",refText:"Reference 71"}),". This ability to interpret incomplete sensory information is essential for navigating the messy reality of everyday perception. And it also offers creative opportunities. In particular, it points to the conclusion that not every detail needs perfect simulation. Strategic hints can prompt audiences to imagine the rest, easing technical demands without sacrificing immersion."]}),"\n",(0,s.jsx)(i.h3,{id:"multisensory-attention",children:"Multisensory attention"}),"\n",(0,s.jsx)("span",{className:"reading-time reading-time--section",role:"note","aria-label":"2 minute read",children:(0,s.jsx)("span",{"aria-hidden":"true",children:"2 min"})}),"\n",(0,s.jsx)(i.p,{children:"Multisensory cues are excellent at attracting and holding attention. Hearing a loud bang alongside a bright flash is more attention-grabbing than either of these alone. And in a performance or interactive exhibit, coordinating sound, light and even gentle tactile cues can effectively steer the audience's focus."}),"\n",(0,s.jsxs)(i.p,{children:["Attention can also be drawn by sensations which violate our expectations",(0,s.jsx)(o.A,{refNum:"72",refText:"Reference 72"}),". This suggests that deliberate deviations from multisensory realism could be used to capture people's attention in interesting ways, where objects may appear to be made of one material but feel unexpectedly different to the touch (e.g., a surface that looks like hard stone but is actually soft), thereby creating surprise and increasing user interest or engagement."]}),"\n",(0,s.jsxs)(i.p,{children:["Once attention is focused on a particular event, it has a number of other important effects. For example, attention and multisensory integration influence each other: attending to an event can strengthen how its sights and sounds are combined, while some integration effects, such as the ventriloquist effect discussed earlier, happen largely automatically and can themselves draw attention ",(0,s.jsx)(o.A,{refNum:"68",refText:"Reference 68"}),". Attention can also selectively amplify some stimuli while suppressing others. The ",(0,s.jsx)(i.em,{children:"cocktail party effect"})," is a classic example whereby you can often tune out background noise to focus on a single conversation",(0,s.jsx)(o.A,{refNum:"73",refText:"Reference 73"}),". Interestingly, attending to lip movements in a noisy room has been found to make a speaker's voice perceptually louder, roughly the same as a +5 dB increase in sound level",(0,s.jsx)(o.A,{refNum:"73",refText:"Reference 73"}),". And this amplification effect occurs in the other senses as well",(0,s.jsx)(o.A,{refNum:"74",refText:"Reference 74"}),", for example heightening visual contrast",(0,s.jsx)(o.A,{refNum:"75",refText:"Reference 75"}),", or making flavours seem richer or more pronounced",(0,s.jsx)(o.A,{refNum:"76",refText:"Reference 76"}),"."]}),"\n",(0,s.jsxs)(i.p,{children:["Attention directed toward emotional stimuli can also heighten affective responses, making emotionally charged experiences more intense",(0,s.jsx)(o.A,{refNum:"77",refText:"Reference 77"}),". Whether it's focusing on a beautifully plated meal or a dramatic moment in a film, attention can amplify the depth of an emotional experience by prioritising and enhancing relevant sensory cues."]}),"\n",(0,s.jsx)(i.h3,{id:"holistic-experiential-integration",children:"Holistic experiential integration"}),"\n",(0,s.jsx)("span",{className:"reading-time reading-time--section",role:"note","aria-label":"1 minute read",children:(0,s.jsx)("span",{"aria-hidden":"true",children:"1 min"})}),"\n",(0,s.jsxs)(i.p,{children:["Audiences absorb far more than just the main show. From their first step into a venue, the lighting, ambient sounds and even the scent of the lobby, all shape their overall impression. Subtle touches, like a textured ticket or a gentle aroma, can make a lasting emotional impact. This highlights the importance of carefully designing the onboarding and offboarding phases of an experience (the ",(0,s.jsxs)(i.em,{children:["whole arc",(0,s.jsx)(o.A,{refNum:"34",refText:"Reference 34"})]}),") to ensure it feels inclusive, enjoyable and comfortable for everyone",(0,s.jsx)(o.A,{refNum:"78",refText:"Reference 78"})," ."]})]})}function f(e={}){let{wrapper:i}={...(0,a.R)(),...e.components};return i?(0,s.jsx)(i,{...e,children:(0,s.jsx)(u,{...e})}):u(e)}},7006(e,i,n){n.d(i,{A:()=>t});let t=n.p+"assets/images/image9-ea1feb56627416465b3d9aacaaad14c9.gif"}}]);